    const allWords = [...addends, resultWord];
    const leadingChars = new Set(allWords.map(w => w[0]));
    const allChars = [...new Set(allWords.join(""))].sort();

    const n = allChars.length;
    const leading = allChars.filter(c => leadingChars.has(c));

    function search(pos, used, mapping) {
      if (pos === n) {
        const toNum = (word) => word.split("").reduce((s, c) => s * 10 + mapping[c], 0);
