const _cost = function cost() {
  return function(books) {
    if (books.length === 0) return 0;

    const PRICE = 800;
    const DISCOUNT = [0, 0, 5, 10, 20, 25];

    // Count copies of each book type
    const counts = new Array(5).fill(0);
    for (const book of books) {
      counts[book]++;
    }

    // Greedy grouping: one copy from each non-empty type per group
    const groups = [];
    while (true) {
      let size = 0;
      for (let j = 0; j < 5; j++) {
        if (counts[j] > 0) {
          counts[j]--;
          size++;
        }
      }
      if (size === 0) break;
      groups.push(size);
    }

    // Optimize: replace (5,3) pairs with (4,4) — saves 40 cents per swap
    groups.sort((a, b) => b - a);
    for (let i = 0; i < groups.length; i++) {
      if (groups[i] === 5) {
        for (let j = groups.length - 1; j > i; j--) {
          if (groups[j] === 3) {
            groups[i] = 4;
            groups[j] = 4;
            groups.sort((a, b) => b - a);
            i = -1; // restart scan
            break;
          }
        }
      }
    }

    // Compute total cost in cents
    let total = 0;
    for (const size of groups) {
      total += size * PRICE * (100 - DISCOUNT[size]) / 100;
    }
    return total;
  };
};

