    "six", "seven", "eight", "nine", "ten"
  ];
  const upper = [
    "No", "One", "Two", "Three", "Four", "Five",
    "Six", "Seven", "Eight", "Nine", "Ten"
  ];
  return function(initialBottlesCount, takeDownCount) {
    const result = [];
    const limit = Math.max(1, initialBottlesCount - takeDownCount + 1);
    for (let count = initialBottlesCount; count >= limit && count > 0; count--) {
      const next = count - 1;
