      if (pins > 10) throw new Error('Pin count exceeds pins on the lane');
      if (this.done) throw new Error('Cannot roll after game is over');

      if (this.currentFrame < 9) {
        if (this.rollInFrame === 0) {
          this.rolls.push(pins);
          if (pins === 10) {
            this.currentFrame++;
          } else {
            this.rollInFrame = 1;
          }
        } else {
          if (this.rolls[this.rolls.length - 1] + pins > 10) {
            throw new Error('Pin count exceeds pins on the lane');
          }
          this.rolls.push(pins);
          this.currentFrame++;
          this.rollInFrame = 0;
        }
      } else {
        if (this.rollInFrame === 0) {
          this.rolls.push(pins);
          this.rollInFrame = 1;
        } else if (this.rollInFrame === 1) {
          const prevRoll = this.rolls[this.rolls.length - 1];
          if (prevRoll !== 10 && prevRoll + pins > 10) {
            throw new Error('Pin count exceeds pins on the lane');
          }
          this.rolls.push(pins);
          this.rollInFrame = 2;
