          const secondRoll = this.rolls[this.rolls.length - 1];
          if (firstRoll === 10 && secondRoll !== 10) {
            if (secondRoll + pins > 10) {
              throw new Error('Pin count exceeds pins on the lane');
            }
          }
          this.rolls.push(pins);
          this.done = true;
        }
      }
    }
