            const region = [];
            const owners = new Set();
            const queue = [[r, c]];
            visited[r][c] = true;
            while (queue.length) {
              const [cr, cc] = queue.shift();
              region.push([cc, cr]);
              for (const [dr, dc] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
