const _RestAPI = function RestAPI() {
  class RestAPI {
    constructor(database = { users: [] }) {
      this.database = database;
      // Sort users array for stable ordering
      this.database.users.sort((a, b) => a.name.localeCompare(b.name));
    }

    get(url) {
      const qIndex = url.indexOf('?');
      const path = qIndex === -1 ? url : url.slice(0, qIndex);
      const query = qIndex === -1 ? '' : url.slice(qIndex + 1);
      const params = new URLSearchParams(query);

      if (path === '/users') {
        const usersParam = params.get('users');
        let users;
        if (usersParam) {
          const names = usersParam.split(',');
          users = this.database.users
            .filter(u => names.includes(u.name))
            .sort((a, b) => a.name.localeCompare(b.name));
        } else {
          users = this.database.users.slice().sort((a, b) => a.name.localeCompare(b.name));
        }
        return { users };
      }

      throw new Error(`Unknown path: ${path}`);
    }

    post(url, payload) {
      if (url === '/add') {
        const name = payload.user;
        const newUser = { name, owes: {}, owed_by: {}, balance: 0 };
        this.database.users.push(newUser);
        this.database.users.sort((a, b) => a.name.localeCompare(b.name));
        return newUser;
      }

      if (url === '/iou') {
        const { lender, borrower, amount } = payload;

        // Find or create lender
        let lenderUser = this.database.users.find(u => u.name === lender);
        if (!lenderUser) {
          lenderUser = { name: lender, owes: {}, owed_by: {}, balance: 0 };
          this.database.users.push(lenderUser);
        }

        // Find or create borrower
        let borrowerUser = this.database.users.find(u => u.name === borrower);
        if (!borrowerUser) {
          borrowerUser = { name: borrower, owes: {}, owed_by: {}, balance: 0 };
          this.database.users.push(borrowerUser);
        }

        // Update lender: borrower owes them money
        if (!lenderUser.owed_by[borrower]) {
          lenderUser.owed_by[borrower] = 0;
        }
        lenderUser.owed_by[borrower] += amount;
        lenderUser.balance += amount;

        // Update borrower: they owe lender money
        if (!borrowerUser.owes[lender]) {
          borrowerUser.owes[lender] = 0;
        }
        borrowerUser.owes[lender] += amount;
        borrowerUser.balance -= amount;

        this.database.users.sort((a, b) => a.name.localeCompare(b.name));

        // Return both users sorted by name
        return {
          users: [lenderUser, borrowerUser].sort((a, b) => a.name.localeCompare(b.name))
        };
      }

      throw new Error(`Unknown path: ${url}`);
    }
  }

  return RestAPI;
};

